files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-block-size: 100dvb;
  margin: 0;
  padding: 2em;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: rgb(156 0 0);
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

span {
  display: block;
  font-weight: bold;
  font-size: clamp(3.125rem, -0.8929rem + 17.8571vw, 12.5rem);
  text-transform: uppercase;
  background-image: url(../images/ferrari.jpg);
  background-position: calc(50% + var(--x, 0px)) calc(50% + var(--y, 0px));
  background-size: 150% auto;
  color: transparent;
  -webkit-background-clip: text;
  background-clip: text;
}
